operation.add:
// ProBG Services
$this->load->language('extension/module/probg_services');
$probg_services = array();
if ($this->user->hasPermission('access', 'extension/probg_services/service')) {
    $probg_services[] = array('name' => $this->language->get('text_menu_services'), 'href' => $this->url->link('extension/probg_services/service', 'user_token=' . $this->session->data['user_token'], true), 'children' => array());
}
if ($this->user->hasPermission('access', 'extension/probg_services/category')) {
    $probg_services[] = array('name' => $this->language->get('text_menu_categories'), 'href' => $this->url->link('extension/probg_services/category', 'user_token=' . $this->session->data['user_token'], true), 'children' => array());
}
if ($this->user->hasPermission('access', 'extension/module/probg_services')) {
    $probg_services[] = array('name' => $this->language->get('text_menu_settings'), 'href' => $this->url->link('extension/module/probg_services', 'user_token=' . $this->session->data['user_token'], true), 'children' => array());
}
if ($probg_services) {
    $data['menus'][] = array('id' => 'menu-probg-services', 'icon' => 'fa-briefcase', 'name' => $this->language->get('text_menu_module'), 'href' => '', 'children' => $probg_services);
}
